html:
{%- set fr = frappe.db.get_value("Customer", doc.franchise, ["customer_name", "primary_address", "mobile_no", "gstin", "food_license_number"], as_dict=1) or {} -%}
{%- set footer = frappe.db.get_single_value("Franchise POS Settings", "bill_footer") -%}
{%- set page_h = 95 + (doc.items | length) * 9 -%}
<style>
	.print-format { page-width: 80mm; page-height: {{ page_h }}mm; margin-top: 3mm; margin-bottom: 3mm; margin-left: 3mm; margin-right: 3mm; }
	.print-format { padding: 0; font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #000; }
	.fb { width: 100%; }
	.fb .c { text-align: center; }
	.fb .r { text-align: right; }
	.fb .name { font-size: 15px; font-weight: bold; }
	.fb .small { font-size: 10px; }
	.fb .line { border-top: 1px dashed #000; margin: 5px 0; }
	.fb table { width: 100%; border-collapse: collapse; }
	.fb td, .fb th { padding: 2px 0; font-size: 11px; vertical-align: top; border: 0; }
	.fb th { text-align: left; border-bottom: 1px solid #000; }
	.fb .total td { font-size: 14px; font-weight: bold; padding-top: 4px; }
</style>
<div class="fb">
	<div class="c name">{{ fr.customer_name or doc.franchise_name }}</div>
	{%- if fr.primary_address %}<div class="c small">{{ fr.primary_address | striptags }}</div>{% endif -%}
	{%- if fr.mobile_no %}<div class="c small">Ph: {{ fr.mobile_no }}</div>{% endif -%}
	{%- if fr.gstin %}<div class="c small">GSTIN: {{ fr.gstin }}</div>{% endif -%}
	{%- if fr.food_license_number %}<div class="c small">FSSAI: {{ fr.food_license_number }}</div>{% endif -%}
	<div class="line"></div>
	<div class="c"><b>{{ "SALE RETURN" if doc.is_return else "BILL" }}</b></div>
	<table>
		<tr><td>No: <b>{{ doc.name }}</b></td><td class="r">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }} {{ (doc.posting_time | string)[:5] }}</td></tr>
		{%- if doc.is_return %}<tr><td colspan="2">Against bill: {{ doc.return_against }}</td></tr>{% endif -%}
		{%- if doc.buyer_name or doc.buyer_mobile %}<tr><td colspan="2">Buyer: {{ doc.buyer_name or "" }} {{ doc.buyer_mobile or "" }}</td></tr>{% endif -%}
	</table>
	<div class="line"></div>
	<table>
		<tr><th>Item</th><th class="r">Qty</th><th class="r">MRP</th><th class="r">Amount</th></tr>
		{%- for d in doc.items %}
		<tr>
			<td>{{ d.item_name }}</td>
			<td class="r">{{ "%g" | format(d.qty) }}</td>
			<td class="r">{{ "%.2f" | format(d.rate) }}</td>
			<td class="r">{{ "%.2f" | format(d.amount) }}</td>
		</tr>
		{%- endfor %}
	</table>
	<div class="line"></div>
	<table>
		<tr><td>Items: {{ doc.items | length }}</td><td class="r">Qty: {{ "%g" | format(doc.total_qty) }}</td></tr>
		<tr class="total"><td>{{ "REFUND" if doc.is_return else "TOTAL" }}</td><td class="r">Rs. {{ "%.2f" | format(doc.grand_total) }}</td></tr>
		<tr><td>Paid by</td><td class="r">{{ doc.payment_mode }}</td></tr>
	</table>
	<div class="line"></div>
	<div class="c small">Prices are MRP, inclusive of all taxes.</div>
	{%- if footer %}<div class="c small">{{ footer }}</div>{% endif -%}
</div>
